def f2(g):
    H=len(g);W=len(g[0])
    for c in set(x for r in g for x in r):
        if any(all(r[j]==c for j in range(W)) for r in g) and any(all(g[i][j]==c for i in range(H)) for j in range(W)):
            lc=c; break
    lr=[i for i in range(H) if all(g[i][j]==lc for j in range(W))][0]
    vcol=[j for j in range(W) if all(g[i][j]==lc for i in range(H))][0]
    cells=[(i,j,g[i][j]) for i in range(H) for j in range(W) if g[i][j]!=lc]
    res=[[g[i][j] for j in range(W) if j!=vcol] for i in range(H) if i!=lr]
    nR,nC=len(res),len(res[0])
    for i,j,cc in cells:
        ri=rj=i if i<lr else i-1
        ci=j if j<vcol else j-1
        variants={(ri,ci),(ri,nC-1-ci),(nR-1-ri,ci),(nR-1-ri,nC-1-ci)}
        for a,b in variants: res[a][b]=cc
    return res
